cypress_script:
describe('Slider Functionality', () => {
  it('should update the value when slider is moved', () => {
    cy.visit('https://demoqa.com/slider');
    cy.get('#slider').invoke('val', 75).trigger('input');
    cy.get('#sliderValue').should('have.value', '75');
  });

  it('should not change the value when slider is not moved', () => {
    cy.visit('https://demoqa.com/slider');
    cy.get('#sliderValue').should('have.value', '25');
  });
});

playwright_script:
import { test, expect } from '@playwright/test';

test.describe('Slider Functionality', () => {
  test('should update the value when slider is moved', async ({ page }) => {
    await page.goto('https://demoqa.com/slider');
    await page.locator('#slider').fill('75');
    await page.locator('#slider').dispatchEvent('input');
    await expect(page.locator('#sliderValue')).toHaveValue('75');
  });

  test('should not change the value when slider is not moved', async ({ page }) => {
    await page.goto('https://demoqa.com/slider');
    await expect(page.locator('#sliderValue')).toHaveValue('25');
  });
});
